-- Cartwheel sample database (generated by scripts/content/make-dataset.mjs)
PRAGMA foreign_keys = ON;
BEGIN;
CREATE TABLE categories (
  category_id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  parent_id INTEGER REFERENCES categories(category_id)
);
CREATE TABLE products (
  product_id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  category_id INTEGER NOT NULL REFERENCES categories(category_id),
  unit_price REAL NOT NULL,
  unit_cost REAL NOT NULL,
  launched_on TEXT NOT NULL,
  is_active INTEGER NOT NULL
);
CREATE TABLE customers (
  customer_id INTEGER PRIMARY KEY,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  country TEXT NOT NULL,
  city TEXT NOT NULL,
  signup_date TEXT NOT NULL,
  segment TEXT NOT NULL,
  referred_by INTEGER REFERENCES customers(customer_id)
);
CREATE TABLE orders (
  order_id INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL REFERENCES customers(customer_id),
  order_date TEXT NOT NULL,
  status TEXT NOT NULL,
  channel TEXT NOT NULL,
  coupon_code TEXT,
  shipping_fee REAL NOT NULL
);
CREATE TABLE order_items (
  order_item_id INTEGER PRIMARY KEY,
  order_id INTEGER NOT NULL REFERENCES orders(order_id),
  product_id INTEGER NOT NULL REFERENCES products(product_id),
  quantity INTEGER NOT NULL,
  unit_price REAL NOT NULL,
  discount REAL NOT NULL
);
CREATE TABLE returns (
  return_id INTEGER PRIMARY KEY,
  order_item_id INTEGER NOT NULL REFERENCES order_items(order_item_id),
  return_date TEXT NOT NULL,
  reason TEXT NOT NULL,
  refund_amount REAL NOT NULL
);
CREATE TABLE employees (
  employee_id INTEGER PRIMARY KEY,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  title TEXT NOT NULL,
  department TEXT NOT NULL,
  manager_id INTEGER REFERENCES employees(employee_id),
  hire_date TEXT NOT NULL,
  salary INTEGER NOT NULL
);
CREATE TABLE support_tickets (
  ticket_id INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL REFERENCES customers(customer_id),
  order_id INTEGER REFERENCES orders(order_id),
  opened_at TEXT NOT NULL,
  closed_at TEXT,
  priority TEXT NOT NULL,
  channel TEXT NOT NULL,
  satisfaction INTEGER,
  agent_id INTEGER REFERENCES employees(employee_id)
);
CREATE TABLE web_sessions (
  session_id INTEGER PRIMARY KEY,
  customer_id INTEGER REFERENCES customers(customer_id),
  started_at TEXT NOT NULL,
  source TEXT NOT NULL,
  device TEXT NOT NULL,
  pages_viewed INTEGER NOT NULL,
  added_to_cart INTEGER NOT NULL,
  purchased INTEGER NOT NULL
);
CREATE INDEX idx_orders_customer ON orders(customer_id);
CREATE INDEX idx_orders_date ON orders(order_date);
CREATE INDEX idx_items_order ON order_items(order_id);
CREATE INDEX idx_items_product ON order_items(product_id);
COMMIT;
